// Scenario: Appointments › Book an appointment (P1, #smoke)
import { fake } from '../../support/helpers.js';
import { env, secret } from '../../support/config.js';

// Tags: @smoke @p1
describe('Appointments › Book an appointment', () => {
  it('Book an appointment', () => {
    const vars = {};
    const last = {};
    // Block: Sign in as the receptionist
    // Open the login page
    cy.visit('/login');
    // Email
    cy.findByLabelText('Email').fill(env.receptionEmail);
    // Password
    cy.findByTestId('password').fill(secret('PASSWORD'));
    // Sign in
    cy.findByRole('button', { name: 'Sign in' }).click();
    // Open the booking form
    cy.visit('/appointments/new');
    // A free date
    cy.then(() => {
      vars.day = fake('date', { direction: 'future', days: 3000 });
    });
    // Patient
    cy.findByLabelText('Patient').select('Chloe Nguyen (PAT-1003)');
    // Doctor
    cy.findByLabelText('Doctor').select('Dr. Mei Lin · Pediatrics');
    // Date
    cy.then(() => {
      cy.findByTestId('appointment-date').fill(String(vars.day));
    });
    // Time
    cy.findByLabelText('Time').select('14:30');
    // Reason
    cy.findByLabelText('Reason for visit').fill('Vaccination');
    // Book
    cy.findByTestId('book-appointment').click();
    // Booked
    cy.findByRole('status').should(($el) => expect($el.text().trim()).to.eq('Appointment booked'));
    // Listed
    cy.then(() => {
      cy.get('#appointments-table').should('contain.text', String(vars.day));
    });
  });
});
